//! A project with `[[review.areas]]`, and the CODEOWNERS file that `botica review export` writes.

use std::path::{Path, PathBuf};
use std::process::Output;

use super::{command, project_in, stderr, stdout};

pub const HEADER: &str = "# Written by `botica review export --format codeowners` from the [[review.areas]] of the\n\
                          # configuration. Change the areas and run the command again; do not edit this file.\n";

pub const FORCED: &str =
    "# Always `platform` (ADR 0018 decision 1), with the owners of every `platform` entry.\n";

pub const PLATFORM: &str =
    "[[review.areas]]\nname = \"platform\"\npaths = [\"ci/**\"]\nowners = [\"@org/platform\"]\n";

pub fn project(name: &str, areas: &str) -> PathBuf {
    project_in("review-export-codeowners", name, Some(areas))
}

/// One entry of `[[review.areas]]`, with `extra` lines such as `approvals = 2`.
pub fn entry(name: &str, paths: &[&str], owners: &[&str], extra: &str) -> String {
    let quoted = |items: &[&str]| {
        items
            .iter()
            .map(|item| format!("\"{item}\""))
            .collect::<Vec<_>>()
            .join(", ")
    };
    format!(
        "\n[[review.areas]]\nname = \"{name}\"\npaths = [{}]\nowners = [{}]\n{extra}",
        quoted(paths),
        quoted(owners)
    )
}

pub fn export(dir: &Path, extra: &[&str]) -> Output {
    let mut args = vec!["review", "export", "--format", "codeowners"];
    args.extend_from_slice(extra);
    command(dir, &args)
}

/// What the export prints with `--output -`, which must succeed.
pub fn printed(dir: &Path, extra: &[&str]) -> String {
    let mut args = vec!["--output", "-"];
    args.extend_from_slice(extra);
    let output = export(dir, &args);
    assert!(output.status.success(), "{}", stderr(&output));
    stdout(&output)
}

/// The lines of the entries on GitHub: after the header and before the forced block.
pub fn github_lines(text: &str) -> &str {
    let text = text.strip_prefix(HEADER).expect("the header comes first");
    let text = text
        .strip_prefix('\n')
        .expect("a blank line after the header");
    text.split_once(&format!("\n{FORCED}"))
        .map_or(text, |(lines, _)| lines)
}

/// The lines of one section of the GitLab file, without its header and without the forced block.
pub fn gitlab_section<'a>(text: &'a str, header: &str) -> &'a str {
    let marker = format!("\n{header}\n");
    let start = text
        .find(&marker)
        .unwrap_or_else(|| panic!("no section `{header}` in:\n{text}"));
    let rest = &text[start + marker.len()..];
    let rest = rest.split_once("\n\n").map_or(rest, |(section, _)| section);
    let rest = rest.split_once(FORCED).map_or(rest, |(lines, _)| lines);
    rest.strip_suffix('\n').unwrap_or(rest)
}
